balance/targets.json:
{
  "formatVersion": 1,
  "_note": "P1.13 balance harness targets. Owner direction 2026-11-24: certain strategies should win more than others. The order below is the intended pecking order by median net worth at the end of the run (Normal). Every value: source A = assumption (owner to tune) with a one-line why. Net worth = cash + savings - credit line owed + site values - project loans (Sim/Game/SystemSteps.cs Snapshot).",
  "run": {
    "quarters": { "value": 80, "source": "A", "why": "20 game years: long enough for at least one full market cycle and for Ruthless's lost relationships to cost it." },
    "seeds": { "value": 20, "source": "A", "why": "Enough games per bot that a 60% pairwise win rate is not noise; fits the 10 minute budget." },
    "maps": { "value": ["glade", "strip"], "source": "A", "why": "The two maps the auto-run tests already play." },
    "fastSeeds": { "value": 2, "source": "A", "why": "Seeds per cell in the slice that runs inside the normal test suite." },
    "maxMinutes": { "value": 10, "source": "A", "why": "Plan-3 P1.13 done-when." }
  },
  "order": {
    "value": ["builder", "flipper", "max_leverage", "safe", "one_type", "ruthless", "land_banker", "do_nothing"],
    "source": "A",
    "why": "Skill wins: the build, lease, refinance, recycle player is on top; risk has the highest ceiling but not the best median; cutting corners fades; doing nothing always loses."
  },
  "pairwiseWinShare": { "value": 0.6, "source": "A", "why": "Each bot beats the one below it (same seed, map, difficulty) in at least this share of games." },
  "doNothingLosesShare": { "value": 0.6, "source": "A", "why": "Owner intent 'doing nothing always loses' read as: Do Nothing's Normal median is below every other bot's median, and every bot beats it in at least the pairwise share. 'Last in every game' (1.0) could never pass alongside the Max Leverage broke band (25 to 40% of games end broke, below Do Nothing's untouched start cash), TODOS N49 b." },
  "broke": {
    "definition": "Tools/balance Broke.cs until P1.25 adds the game's shared rule: broke when net worth is at or below zero for 2 quarter ends in a row, or cash + savings + credit room cannot cover what the quarter drained for 2 quarters in a row. Plain-loan and stacked projects count the same. A game that recovers is recorded as broke at q, recovered at q. The broke rate counts games broke at the end or broke 4+ quarters in a row (TODOS N49 a).",
    "maxLeverage": { "value": [0.25, 0.40], "source": "A", "why": "Risk must bite: Max Leverage goes broke in a quarter to two fifths of games on Normal." },
    "safe": { "value": [0.0, 0.02], "source": "A", "why": "The careful player almost never goes broke." }
  },
  "ceiling": {
    "maxLeverageTop10OverBuilderTop10": { "value": true, "source": "A", "why": "Max Leverage's best 10% of games beat Builder's best 10%: the big swing can pay off." }
  },
  "arc": {
    "ruthlessAheadOfSafeAtQuarter": { "value": 20, "source": "A", "why": "Ruthless leads Safe (median net worth) at year 5." },
    "ruthlessBehindSafeAtEnd": { "value": true, "source": "A", "why": "Ruthless trails Safe by the end as people stop dealing with it." }
  },
  "difficulty": {
    "easy": { "safeWithinShareOfTop": { "value": 0.85, "source": "A", "why": "On Easy, Safe's median is at least 85% of the top bot's median." }, "maxBrokeAny": { "value": 0.10, "source": "A", "why": "On Easy almost nobody goes broke: no bot above 10%." } },
    "tycoon": { "builderLeadOverSecondAtLeastNormal": { "value": true, "source": "A", "why": "On Tycoon, Builder's lead over the runner-up is at least its Normal lead." }, "maxLeverageBrokeAboveNormal": { "value": true, "source": "A", "why": "On Tycoon, Max Leverage goes broke more often than on Normal." } }
  },
  "flags": {
    "maxEquityMultiplePerYear": { "value": 3.0, "source": "A", "why": "No bot should triple its starting net worth every year on average; above that is an exploit." },
    "unexplainedCashTolerance": { "value": 1.0, "source": "A", "why": "Cash may not rise in a quarter by more than this many dollars beyond what rent, sales, loans, refinances and rewards explain." },
    "statPinnedQuarters": { "value": 8, "source": "A", "why": "A stat (honor, fame, heat, a relationship) stuck at its maximum this many quarters in a row is a warning; it is reported and does not fail the gate. Occupancy is left out: 100% leased is healthy (TODOS N49 c)." },
    "equityMultipleMinQuarters": { "value": 20, "source": "A", "why": "The equity multiple flag only runs on games of 20+ quarters: on a 2 quarter run, annualizing (final/start)^(4/q) turns normal leverage swings into a fake exploit (TODOS N49 h)." }
  }
}

