camera.json:
{
  "_note": "Third person camera defaults, GTA V style (owner, plan-5 additions item 3). Shared by the web client (Web/Client) and later the Unity Cinemachine rigs. Distances in meters, angles in degrees, times in seconds. Source A = estimate of the GTA V default 'medium' chase and on-foot cameras, owner to tune by feel. Sim/Camera/CameraRig.cs derives the resting pose; Tests/GladeParks.Sim.Tests/Camera pins the default angle.",
  "car": {
    "baseDistance": { "value": 1.7, "source": "A", "why": "Fixed part of the chase distance behind the car's center." },
    "distancePerLength": { "value": 0.92, "source": "A", "why": "Distance grows with the vehicle: a 4.7 m sedan rests about 6 m behind its center, as GTA V's medium chase camera does." },
    "heightAboveRoof": { "value": 0.55, "source": "A", "why": "Camera sits just above the roof line, so the car fills the lower middle of the frame." },
    "lookAtHeight": { "value": 0.9, "source": "A", "why": "Aim point height above the ground: about the car's beltline." },
    "lookAhead": { "value": 1.5, "source": "A", "why": "Aim point is a little ahead of the car's center, so the road ahead shows." },
    "fov": { "value": 50, "source": "A", "why": "Vertical field of view at rest, close to GTA V's default." },
    "fovAtTopSpeed": { "value": 56, "source": "A", "why": "Field of view widens a little with speed for a sense of pace." },
    "followLag": { "value": 0.12, "source": "A", "why": "Position spring time: the camera trails the car slightly and swings wide in turns." },
    "yawLag": { "value": 0.28, "source": "A", "why": "Heading spring time: it settles back behind the car after a turn." },
    "recenterDelay": { "value": 1.5, "source": "A", "why": "Seconds with no look input before the camera eases back behind the car." },
    "recenterSpeed": { "value": 120, "source": "A", "why": "Degrees a second while easing back behind the car." },
    "lookPitchMin": { "value": -15, "source": "A", "why": "Free look: lowest pitch (looking up from below the default)." },
    "lookPitchMax": { "value": 40, "source": "A", "why": "Free look: highest pitch (looking down on the car)." },
    "lookBehind": { "value": true, "source": "A", "why": "A look-behind button flips the camera to face back." },
    "blendTime": { "value": 0.6, "source": "A", "why": "Seconds the view takes to swing between the walking camera and the chase camera when you get in or out (Unity plan-9, slot p2)." }
  },
  "onFoot": {
    "distance": { "value": 2.8, "source": "A", "why": "Close enough to read the street, far enough to see the player whole from the knees up." },
    "height": { "value": 1.75, "source": "A", "why": "Slightly above shoulder height." },
    "lookAtHeight": { "value": 1.45, "source": "A", "why": "Aim at the upper back, so the player sits a little below center." },
    "shoulderOffset": { "value": 0.0, "source": "A", "why": "Centered behind the player like GTA V's default walk camera (aiming would move it to the right shoulder)." },
    "fov": { "value": 50, "source": "A", "why": "Same field of view as the car at rest." },
    "followLag": { "value": 0.08, "source": "A", "why": "Tighter spring than the car." },
    "recenterDelay": { "value": 1.5, "source": "A", "why": "Eases back behind the player once they walk with no look input." },
    "recenterSpeed": { "value": 90, "source": "A", "why": "Degrees a second." },
    "lookPitchMin": { "value": -30, "source": "A", "why": "Free look floor." },
    "lookPitchMax": { "value": 60, "source": "A", "why": "Free look ceiling." },
    "collisionPullIn": { "value": true, "source": "A", "why": "Walls pull the camera in rather than letting it clip through." }
  },
  "sedan": {
    "length": { "value": 4.7, "source": "A", "why": "Reference vehicle for the default angle test." },
    "height": { "value": 1.45, "source": "A", "why": "Reference vehicle roof height." }
  },
  "overhead": {
    "pitch": { "value": 55, "source": "A", "why": "Build mode looks down at 55 degrees: steep enough to read the grid, shallow enough to see building sides." },
    "height": { "value": 140, "source": "A", "why": "Starting camera height in meters above the site center: a whole small site fits on screen." },
    "zoomMin": { "value": 40, "source": "A", "why": "Closest the build camera comes, in meters: about one tower block fills the view." },
    "zoomMax": { "value": 700, "source": "A", "why": "Farthest the build camera goes, in meters: the longest home map fits." },
    "zoomStep": { "value": 0.12, "source": "A", "why": "Share of the distance one wheel notch or key press zooms." },
    "rotateStep": { "value": 15, "source": "A", "why": "Degrees one rotate key press turns the view around the site center." },
    "priorityAbovePlayer": { "value": 10, "source": "A", "why": "Build camera priority above the live player camera (PlayerCameras.Live) so it wins the blend while build mode is open." },
    "panSpeed": { "value": 120, "source": "A", "why": "Meters a second WASD slides the build camera aim point." }
  },
  "build": {
    "followLag": { "value": 0.25, "source": "A", "why": "Seconds the build camera's aim point takes to catch up with the cursor cell: quick enough to keep up with key presses, slow enough not to jerk (N253)." },
    "edgeMargin": { "value": 0.2, "source": "A", "why": "Share of the frame on each side the cursor may reach before the camera moves, so small moves near the middle leave the view still." },
    "maxPanPerSecond": { "value": 400, "source": "A", "why": "Fastest the aim point slides, in meters a second: crosses the 808 m glade site in about two seconds." }
  }
}

