ceremonies/ceremonies.json:
{
  "_note": "P5.9 ceremonies. One per construction stage change: groundbreaking when the build starts, top beam at topping out (framing done), ribbon cutting at opening. Each plays as a short skippable cutscene through Sim/Cutscenes. Turnout = (base + fame x perFame + honor x perHonor) x the kind's scale, clamped to min and max. People who helped on the project show up.",
  "turnout": {
    "base": { "value": 20, "source": "P5.9 owner prompt: crowd size follows fame and honor", "why": "A first project still draws family, crew and a few neighbors." },
    "perFame": { "value": 3, "source": "P5.9", "why": "Fame brings press and fans; 3 people per fame point puts a famous player in the hundreds." },
    "perHonor": { "value": 1, "source": "P5.9", "why": "Honor brings the neighbors and the city; weighted below fame because honest work is quieter." },
    "min": { "value": 8, "source": "P5.9", "why": "Even a bad name gets the crew and a few people." },
    "max": { "value": 2000, "source": "P5.9", "why": "A cap that a city block can hold." }
  },
  "helpers": {
    "minScore": { "value": 60, "source": "Data/people relationship scale 0 to 100", "why": "Only people who think well of you come out to celebrate." },
    "max": { "value": 4, "source": "P5.9", "why": "A few faces the player knows, kept short." }
  },
  "kinds": [
    { "id": "groundbreaking", "template": "crowd_moment", "title": "Golden shovel",
      "scale": { "value": 0.5, "source": "P5.9", "why": "Groundbreakings are small: a lot and a few shovels." },
      "captions": [
        { "speaker": "player", "text": "Golden shovels up. {building} starts today." },
        { "speaker": null, "text": "{turnout} people came out for {company}." } ] },
    { "id": "topping_out", "template": "crowd_moment", "title": "Top beam",
      "scale": { "value": 0.75, "source": "P5.9", "why": "The crew and the city come to sign the last beam." },
      "captions": [
        { "speaker": null, "text": "Everyone signs the last beam before it goes up." },
        { "speaker": "player", "text": "{building} is as tall as it gets. {turnout} people watched." } ] },
    { "id": "ribbon_cutting", "template": "crowd_moment", "title": "Ribbon cutting",
      "scale": { "value": 1.0, "source": "P5.9", "why": "Opening day is the biggest of the three." },
      "captions": [
        { "speaker": "player", "text": "Big scissors. One cut. {building} is open." },
        { "speaker": null, "text": "{turnout} people came to see it open." } ] }
  ]
}

