    "low": { "recipes": ["timelapse", "dollyOrbit"], "mood": "golden_hour", "typeWord": "Shops", "why": "Low buildings get a dolly in and a short orbit after the timelapse." },
    "tower": { "recipes": ["timelapse", "crane"], "mood": "golden_hour", "typeWord": "Tower", "why": "Towers of 6 floors or more get the crane reveal." },
    "topTier": { "recipes": ["timelapse", "crane", "lightsOn"], "mood": "epic_night", "typeWord": "Tower", "dropCraneLanding": true, "why": "Owner call 50: same rule as the landmark. Keep the timelapse, drop the crane landing so the crane lands straight on the lights: 6.5 + 4 + 4 = 14.5 s, under the 15 s cap." },
    "landmark": { "recipes": ["timelapse", "crane", "lightsOn"], "mood": "golden_hour", "typeWord": "Landmark", "dropCraneLanding": true, "why": "Owner call 50: same rule as top tier. A landmark gets all three; with the hero low landing it runs 17 s, so the crane lands straight on the lights. The landmark flag adds only the short timelapse (6 s), so 14 s." }
