city/drive.json:
{
  "_note": "P7.9 drive-past lot reveal. Driving within radiusMeters of a city lot whose dealSource is for_sale_sign can turn that sign into a listing in the deal market. Tuned in round 47 (N280); owner to tune by feel.",
  "radiusMeters": { "value": 40, "source": "A", "why": "About the width of a city lot plus the street in front of it. A sign is readable from a car in the near lane, so you must drive the street the lot faces, not the next one over (blocks in Data/city/city.json run about 100 m)." },
  "revealChance": { "value": 0.45, "source": "A", "why": "Under half the signs you pass turn into a real lead: the rest are already under contract or the owner will not talk. With four sign lots on the map that is about two finds per full loop, so driving is a search, not a checklist." },
  "perQuarterCap": { "value": 2, "source": "A", "why": "At most two new leads a quarter from driving. The broker feed brings about four listings a quarter, so driving adds to it without replacing it, and one loop of the city cannot empty every sign at once." },
  "throttleSeconds": { "value": 0.5, "source": "A", "why": "Client only: how often the car asks the sim whether it passed a sign. At 25 m/s top speed the car moves about 12 m between checks, well inside the 40 m radius, so no sign is skipped. Not a game rule." },
  "missRerollQuarters": { "value": 1, "source": "A", "why": "Owner call 72: a sign that gave no lead can be tried again after this many quarters, so no game is left with nothing to find by driving. One quarter means a missed sign rolls at most once a quarter, not on every pass. 0 makes a miss permanent." }
}

