story/cutscenes.json:
{
  "_note": "10 story cutscenes from the plan's 5 templates, plus 10 title cards (R48: chapter 1 to 9 and the comeback, Trigger chapter:<id> and story:comeback) (port-plan Cutscenes section). 15-45 s, always skippable, captions only (Id is stable for voice later). Tokens are filled at play time from the character, company, and the actual building. Teen rating, no real brands. cs_ending has four variants (Straight Shooter, Fair Dealer, Hard Dealer, Shark; R48 outline) and counts as one beat.",
  "MinSeconds": 15,
  "MaxSeconds": 45,
  "Tokens": [
    "owners_word",
    "player",
    "company",
    "they",
    "them",
    "their",
    "building",
    "building_id",
    "lot",
    "destination",
    "destination_name"
  ],
  "Templates": [
    {
      "Id": "site_flyover",
      "Name": "Site flyover + caption",
      "RequiredParams": [
        "site"
      ]
    },
    {
      "Id": "construction_timelapse",
      "Name": "Construction timelapse",
      "RequiredParams": [
        "building",
        "from_stage",
        "to_stage"
      ]
    },
    {
      "Id": "two_people_talking",
      "Name": "Two people talking",
      "RequiredParams": [
        "left",
        "right",
        "place"
      ]
    },
    {
      "Id": "crowd_moment",
      "Name": "Crowd moment",
      "RequiredParams": [
        "place",
        "crowd",
        "mood"
      ]
    },
    {
      "Id": "travel",
      "Name": "Travel",
      "RequiredParams": [
        "from",
        "to",
        "vehicle"
      ]
    }
  ],
  "Cutscenes": [
    {
      "Id": "cs_first_land",
      "Template": "site_flyover",
      "Title": "Your first land",
      "Trigger": "mission:m1_first_lot",
      "Duration": 20,
      "Params": {
        "site": "{lot}",
        "district": "glade"
      },
      "Shots": [
        {
          "At": 0,
          "Duration": 12,
          "Camera": "crane_up",
          "Focus": "{lot}"
        },
        {
          "At": 12,
          "Duration": 8,
          "Camera": "orbit",
          "Focus": "{lot}"
        }
      ],
      "Captions": [
        {
          "Id": "cs_first_land.1",
          "At": 1.0,
          "Duration": 2.7,
          "Speaker": null,
          "Text": "This dirt belongs to {company} now."
        },
        {
          "Id": "cs_first_land.4",
          "At": 4.7,
          "Duration": 2.7,
          "Speaker": null,
          "Text": "Locals call it the Triple Flop."
        },
        {
          "Id": "cs_first_land.4b",
          "At": 8.4,
          "Duration": 2.25,
          "Speaker": null,
          "Text": "Three shops died here."
        },
        {
          "Id": "cs_first_land.5",
          "At": 11.65,
          "Duration": 3.6,
          "Speaker": null,
          "Text": "Cedar Glade has a new developer in town."
        },
        {
          "Id": "cs_first_land.3",
          "At": 16.25,
          "Duration": 2.25,
          "Speaker": "player",
          "Text": "Okay. Let's make something good."
        }
      ]
    },
    {
      "Id": "cs_meet_mentor",
      "Template": "two_people_talking",
      "Title": "Meet Lorraine",
      "Trigger": "mission:m1_meet_mentor",
      "Duration": 30,
      "Params": {
        "left": "player",
        "right": "mentor",
        "place": "creekside_diner"
      },
      "Shots": [
        {
          "At": 0,
          "Duration": 10,
          "Camera": "two_shot",
          "Focus": "both"
        },
        {
          "At": 10,
          "Duration": 10,
          "Camera": "over_shoulder",
          "Focus": "mentor"
        },
        {
          "At": 20,
          "Duration": 10,
          "Camera": "over_shoulder",
          "Focus": "player"
        }
      ],
      "Captions": [
        {
          "Id": "cs_meet_mentor.1",
          "At": 1.0,
          "Duration": 4.68,
          "Speaker": "mentor",
          "Text": "So you're {player}. I hear you bought that empty lot."
        },
        {
          "Id": "cs_meet_mentor.2",
          "At": 6.68,
          "Duration": 3.75,
          "Speaker": "player",
          "Text": "I did. Now I need to fill it."
        },
        {
          "Id": "cs_meet_mentor.3",
          "At": 11.43,
          "Duration": 5.15,
          "Speaker": "mentor",
          "Text": "Build what the neighbors need, and they'll keep you in business."
        },
        {
          "Id": "cs_meet_mentor.5",
          "At": 17.58,
          "Duration": 2.81,
          "Speaker": null,
          "Text": "She does not shake your hand."
        },
        {
          "Id": "cs_meet_mentor.5b",
          "At": 21.39,
          "Duration": 2.34,
          "Speaker": null,
          "Text": "She tips her hat."
        },
        {
          "Id": "cs_meet_mentor.4",
          "At": 24.73,
          "Duration": 3.75,
          "Speaker": "mentor",
          "Text": "Call me when you get stuck. You will."
        }
      ]
    },
    {
      "Id": "cs_groundbreaking",
      "Template": "construction_timelapse",
      "Title": "Break ground",
      "Trigger": "mission:m1_start",
      "Duration": 25,
      "Params": {
        "building": "{building_id}",
        "from_stage": "dirt",
        "to_stage": "framed"
      },
