        }
      ],
      "Captions": [
        {
          "Id": "cs_groundbreaking.1",
          "At": 1.0,
          "Duration": 3.82,
          "Speaker": null,
          "Text": "Day one. Shovels in the ground."
        },
        {
          "Id": "cs_groundbreaking.4",
          "At": 5.82,
          "Duration": 3.82,
          "Speaker": null,
          "Text": "Gerald watches from the water tower."
        },
        {
          "Id": "cs_groundbreaking.4b",
          "At": 10.64,
          "Duration": 3.82,
          "Speaker": null,
          "Text": "He is still eating your sandwich."
        },
        {
          "Id": "cs_groundbreaking.2",
          "At": 15.46,
          "Duration": 3.82,
          "Speaker": null,
          "Text": "Week by week, {building} goes up."
        },
        {
          "Id": "cs_groundbreaking.3",
          "At": 20.28,
          "Duration": 3.18,
          "Speaker": null,
          "Text": "{company} is building."
        }
      ]
    },
    {
      "Id": "cs_rival_challenge",
