traffic/mobil.json:
{
  "formatVersion": 1,
  "_note": "P2.4 MOBIL lane change tunables. Read by Sim/Traffic/MobilParams.cs. Model: Kesting, Treiber and Helbing 2007, General lane-changing model MOBIL for car-following models, Transportation Research Record 1999, pp. 86 to 94. Values marked R are the paper's suggested values as recalled by the builder; check against the paper before calling them final.",
  "mobil": {
    "safeBrakeMps2": { "value": 4.0, "source": "R", "why": "Safety limit b_safe = 4 m/s2: the new follower in the target lane may never need to brake harder than this. Kesting, Treiber and Helbing 2007, suggested value, well under the 9 m/s2 hard floor." },
    "thresholdMps2": { "value": 0.1, "source": "R", "why": "Changing threshold delta a_th = 0.1 m/s2: the total gain must beat this or the car stays put, so tiny gains do not cause weaving. Kesting, Treiber and Helbing 2007, suggested value." },
    "politeness": { "value": 0.5, "source": "R", "why": "Politeness p: 0 is selfish, 1 weighs the others' loss as much as the driver's own gain. Kesting, Treiber and Helbing 2007 use 0 to 0.5 in their runs; 0.5 is the polite end." },
    "rightBiasMps2": { "value": 0.3, "source": "R", "why": "Keep right bias delta a_bias = 0.3 m/s2: a move toward the curb lane gets this much extra gain and a move toward the center lane loses it. Kesting, Treiber and Helbing 2007, suggested value for keep right rules." },
    "cooldownS": { "value": 3.0, "source": "A", "why": "Least time between two lane changes by one car, so a car cannot flick back and forth inside one gap. About one lane change maneuver. Owner to tune." },
    "noChangeNearEndM": { "value": 50.0, "source": "A", "why": "No lane changes in the last 50 m before a stop line. The MOBIL check here ignores signals, so cars stop weaving where the light decides who moves. Owner to tune." }
  }
}

traffic/traffic.json:
{
  "formatVersion": 1,
  "_note": "P2.2 lane graph and P2.3 IDM car following tunables. Read by Sim/Traffic/TrafficParams.cs. IDM values are the motorway set from Treiber, Hennecke and Helbing 2000 (Phys. Rev. E 62, 1805, Table 1); desired speed comes from each lane's posted speed instead of their 120 km/h. Signal timing is an assumption for the owner to tune.",
  "idm": {
    "timeGapS": { "value": 1.6, "source": "R", "why": "Safe time headway T = 1.6 s, Treiber, Hennecke and Helbing 2000, Table 1." },
    "maxAccelMps2": { "value": 0.73, "source": "R", "why": "Maximum acceleration a = 0.73 m/s2, Treiber, Hennecke and Helbing 2000, Table 1." },
    "comfortBrakeMps2": { "value": 1.67, "source": "R", "why": "Comfortable deceleration b = 1.67 m/s2, Treiber, Hennecke and Helbing 2000, Table 1." },
    "minGapM": { "value": 2.0, "source": "R", "why": "Jam distance s0 = 2 m, Treiber, Hennecke and Helbing 2000, Table 1." },
    "delta": { "value": 4.0, "source": "R", "why": "Acceleration exponent delta = 4, Treiber, Hennecke and Helbing 2000, Table 1." },
    "carLengthM": { "value": 5.0, "source": "R", "why": "Vehicle length 5 m, Treiber, Hennecke and Helbing 2000, Table 1." },
    "maxBrakeMps2": { "value": 9.0, "source": "A", "why": "Hard floor on braking so an emergency stop stays physical (about 0.9 g on dry pavement). IDM can ask for more in a cut in; we clamp and log it." },
    "stepS": { "value": 0.1, "source": "A", "why": "Fixed sim step. Treiber recommends the ballistic update with steps up to about 0.5 s; 0.1 s keeps stops at lines crisp." }
  },
  "signals": {
    "leftGreenS": { "value": 10.0, "source": "A", "why": "Protected left arrow. Long enough for about 4 cars from a short bay. Owner to tune." },
    "throughGreenS": { "value": 30.0, "source": "A", "why": "Through and right green per axis. Gives a cycle near 70 s, a common city cycle length. Owner to tune." },
    "yellowS": { "value": 4.0, "source": "A", "why": "Yellow change interval. Common practice is 3 to 6 s, rising with approach speed; 4 s suits 55 to 65 km/h streets." },
    "allRedS": { "value": 2.0, "source": "A", "why": "All red clearance between phases so the last car out clears the box. Common practice is 1 to 2 s." }
  },
  "geometry": {
    "stopLineSetbackM": { "value": 1.0, "source": "A", "why": "Stop line distance behind the crossing road's curb. The crosswalk sits on the other side of the curb line in map.json; 1 m keeps the stop line on the carriageway." },
    "turnPocketM": { "value": 30.0, "source": "A", "why": "Left turn bay length when the map says the approach has a turn lane. Clamped to the leg length. About 6 cars. Owner to tune." },
    "turnSpeedKph": { "value": 25.0, "source": "A", "why": "Desired speed through a left or right turn at a city corner. A 10 to 15 m turn radius at about 0.4 g side force gives 22 to 27 km/h." },
    "turnSamples": { "value": 8, "source": "A", "why": "Segments per turn curve. Enough for a smooth debug view and a conflict check." }
  }
}

