{
  "formatVersion": 1,
  "note": "Overhead info views (P1.7). Each view tints the site by one value. Ramps are colorblind-safe: viridis, cividis, magma and purple-orange (ColorBrewer PuOr), checked for red-green colorblindness. 'min'/'max' fix the scale so colors mean the same thing on every site. Cells with no value get no tint. Summary text uses {name} slots.",
  "order": ["land", "traffic", "vacancy", "demand", "transit"],
  "views": {
    "land": {
      "title": "Land value",
      "min": 0.85, "max": 1.15,
      "ramp": ["#440154", "#3b528b", "#21918c", "#5ec962", "#fde725"],
      "legendLow": "Worth less (trucks, drive-thrus nearby)",
      "legendHigh": "Worth more (parks, water nearby)",
      "summary": { "high": "Land here is worth about {pct}% more than normal.", "low": "Land here is worth about {pct}% less than normal.", "even": "Land here is worth about normal.", "none": "Land value is not on for this site yet." }
    },
    "traffic": {
      "title": "Traffic",
      "min": 0, "max": 400,
      "ramp": ["#00204d", "#414d6b", "#7c7b78", "#bcaf6f", "#ffea46"],
      "legendLow": "Quiet",
      "legendHigh": "Busy at rush hour",
      "summary": { "some": "Busiest path: about {cars} cars at evening rush. {trucks} trucks a day.", "none": "No cars yet. Build a driveway and something to drive to." }
    },
    "vacancy": {
      "title": "Empty space",
      "min": 0, "max": 1,
      "ramp": ["#fcfdbf", "#fc8961", "#b73779", "#51127c", "#000004"],
      "legendLow": "Full of tenants",
      "legendHigh": "Empty",
      "summary": { "some": "{pct}% of your space is empty.", "full": "Every space is rented.", "none": "No spaces to rent yet." }
    },
    "demand": {
      "title": "Demand",
      "min": 0, "max": 1.4,
      "ramp": ["#b35806", "#f1a340", "#f7f7f7", "#998ec3", "#542788"],
