    "source": "A",
    "why": "Half the shoulder width in meters."
  },
  "carLength": {
    "value": 4.7,
    "source": "Data/art/models.json cars.player sedan-sports.glb lengthU 2.55 x car-kit metersPerUnit 1.843137; Data/camera.json sedan.length 4.7",
    "why": "Length of the player sedan in meters, so the box collider matches the car kit model."
  },
  "carWidth": {
    "value": 2.4,
    "source": "Data/art/models.json cars.player widthU 1.3 x 1.843137 = 2.40",
    "why": "Width of the player sedan model in meters, so the collider covers the drawn car."
  },
  "carHeight": {
    "value": 2.05,
    "source": "Data/art/models.json cars.player heightU 1.1 x 1.843137 = 2.03, rounded up",
    "why": "Roof height of the player sedan model in meters, so the collider covers the drawn car."
  },
  "carMass": {
    "value": 1800,
    "source": "A",
    "why": "Kilograms; a light pickup."
  },
  "wheelRadius": {
    "value": 0.4,
    "source": "A",
    "why": "Radius of the drawn wheels in meters."
  },
  "maxSteerRate": {
    "value": 90,
    "source": "A",
    "why": "Degrees a second the car turns at full lock at low speed, before the steer assist trims it."
  },
  "steerFullSpeed": {
    "value": 3,
    "source": "A",
    "why": "Meters a second at which steering reaches full strength, so a parked car does not spin in place."
  },
  "steerAtTopSpeed": {
    "value": 0.35,
    "source": "A",
    "why": "Share of full steering left at top speed when the car's steer assist is 1, so a fast car does not spin out."
  },
  "slipDampRate": {
    "value": 12,
    "source": "A",
    "why": "How fast sideways slide dies away, per second at grip 1: the car carves rather than drifts."
  },
  "brakeDecel": {
    "value": 9,
    "source": "A",
    "why": "Meters a second squared of braking from S, about a hard stop on dry road."
  },
  "reverseShare": {
    "value": 0.3,
    "source": "A",
    "why": "Share of top speed the car may reach in reverse."
  },
  "rollingDrag": {
    "value": 0.6,
    "source": "A",
    "why": "Meters a second squared the car slows by when nothing is pressed."
  },
  "enterReach": {
    "value": 3.5,
    "source": "A",
    "why": "How close in meters the player must stand to the car, center to body, to get in."
  },
  "exitMaxSpeed": {
    "value": 2.0,
    "source": "A",
    "why": "Fastest the car may be moving, meters a second, for the player to get out."
  },
  "exitSideOffset": {
    "value": 1.8,
    "source": "A",
    "why": "Meters to the left of the car's center where the player stands after getting out."
  },
  "uprightAfter": {
    "value": 2.0,
    "source": "A",
    "why": "Seconds on its side or roof before the car rights itself."
  },
  "bodyColor": {
    "value": "#3359b3",
    "source": "round p9-1 PlayerSpawner literal (0.20, 0.35, 0.70)",
    "why": "Blue jacket so the person reads against grass, road and tan lots."
  },
  "carColor": {
    "value": "#9e4d2e",
    "source": "round p9-1 PlayerSpawner literal (0.62, 0.30, 0.18)",
    "why": "Rust red so the player car stands apart from grey roads and traffic."
  },
  "wheelColor": {
    "value": "#141414",
    "source": "round p9-1 PlayerSpawner literal (0.08, 0.08, 0.08)",
    "why": "Near-black tires."
  },
  "characterModelYaw": {
    "value": 0,
    "source": "A; checked in Docs/playtests/unity/2026-11-27/w0-3-onfoot.png",
    "why": "Extra degrees the mini character turns on top of art.json characterYawDeg so it faces the way the body walks."
  },
  "carModelYaw": {
    "value": 0,
    "source": "A; checked in Docs/playtests/unity/2026-11-27/w0-3-car.png",
    "why": "Extra degrees the car kit model turns on top of art.json carYawDeg so its nose points the way the car drives."
  },
  "characterGroundOffset": {
    "value": 0,
    "source": "A",
    "why": "Meters the character model is raised above the feet point; ArtLibrary already puts the model base at zero."
  },
  "carGroundOffset": {
    "value": 0,
    "source": "A",
    "why": "Meters the car model is raised above the collider bottom; ArtLibrary already puts the wheels' base at zero."
  },
  "animIdleClip": {
    "value": "idle",
    "source": "clip names in ThirdParty/kenney/mini-characters character-*.glb",
    "why": "Clip the character plays standing still."
  },
  "animWalkClip": {
    "value": "walk",
    "source": "clip names in ThirdParty/kenney/mini-characters character-*.glb",
    "why": "Clip the character plays at walking speed."
  },
  "animRunClip": {
    "value": "sprint",
    "source": "clip names in ThirdParty/kenney/mini-characters character-*.glb",
    "why": "Clip the character plays while running."
  },
  "animIdleBelowSpeed": {
    "value": 0.1,
    "source": "A",
    "why": "Meters a second under which the character counts as standing still."
  },
  "animRunFromSpeed": {
    "value": 3.85,
    "source": "A; halfway between walkSpeed 2.2 and runSpeed 5.5",
    "why": "Meters a second at and above which the walk clip gives way to the run clip."
  },
  "animCrossFade": {
    "value": 0.15,
    "source": "A",
    "why": "Seconds one clip blends into the next so the switch does not pop."
  },
  "carTipUpDot": {
    "value": 0.5,
    "source": "round p9-1 ArcadeCarController literal 0.5f",
    "why": "The car counts as tipped when its up axis dotted with world up drops below this (about 60 degrees of lean)."
  }
}

